create table eba_demo_dg_emp (
    empno    number(4, 0)
        generated by default on null as identity
    not null enable,
    ename    varchar2(50 byte),
    job      varchar2(50 byte),
    mgr      number(4, 0),
    hiredate date,
    sal      number(7, 2),
    comm     number(7, 2),
    deptno   number(4, 0)
);

alter table eba_demo_dg_emp
    add constraint eba_demo_dg_emp_pk primary key ( empno )
        using index enable;


